fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let gx: i32 = 70;
    let gy: i32 = 120;
    let cs: i32 = 56;
    let mut v: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        let cx: i32 = (px - gx) / cs;
        let cy: i32 = (py - gy) / cs;
        if px >= gx && py >= gy && cx < 3 && cy < 3 {
            let d: i32 = cy * 3 + cx + 1;
            if v < 100000 {
                v = v * 10 + d;
                host::display::state_set(0, v);
            }
        }
        if px >= gx && px < gx + cs * 3 - 4 && py >= gy + cs * 3 && py < gy + cs * 3 + 36 {
            v = 0;
            host::display::state_set(0, 0);
        }
    }
    host::display::state_set(1, down);
    host::display::clear(0x101010);
    host::display::fill_rect(gx - 2, 58, cs * 3, 44, 0x303030);
    host::display::fill_rect(gx, 60, cs * 3 - 4, 40, 0x000000);
    host::display::draw_number(gx + 8, 72, v, 0x00ff88, 2);
    let mut i: i32 = 0;
    while i < 9 {
        let x: i32 = gx + (i % 3) * cs;
        let y: i32 = gy + (i / 3) * cs;
        let mut c: i32 = 0x282830;
        if down == 1 && px >= x && px < x + cs - 4 && py >= y && py < y + cs - 4 {
            c = 0x485060;
        }
        host::display::fill_rect(x, y, cs - 4, cs - 4, c);
        host::display::draw_char(x + 20, y + 18, 49 + i, 0xffffff, 2);
        i = i + 1;
    }
    host::display::fill_rect(gx, gy + cs * 3, cs * 3 - 4, 36, 0x603030);
    host::display::draw_string(gx + 60, gy + cs * 3 + 12, "CLR", 0xffffff, 1);
    host::display::present();
}
